public class Util {
    public static <T> T identity(T x) { return x; }
    public static <T extends Comparable<? super T>> T max(java.util.List<T> list) {
        T best = list.get(0);
        for (T t : list) { if (t.compareTo(best) > 0) best = t; }
        return best;
    }
}

